import { useState } from "react";
import axios from "axios";
import SearchBar from "../components/SearchBar";
import "./style.css"; // Import your new CSS

function Home() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleSearch = async (location) => {
    setLoading(true);
    try {
      const res = await axios.get(
        `http://localhost:5000/search?location=${encodeURIComponent(location)}`
      );
      setResults(res.data);
    } catch (error) {
      alert("Error fetching homes");
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="home"
      style={{ backgroundImage: "url(http://localhost:5000/home_gen.jpg)" }}
    >
      <h1>WELCOME TO NEST FINDER</h1>
      <SearchBar onSearch={handleSearch} />
      <div
        style={{
          marginTop: "2rem",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: "1rem",
        }}
      >
        {loading && (
          <div className="loading-spinner">
            <img src="https://i.gifer.com/ZZ5H.gif" alt="Loading..." />
          </div>
        )}
        {results.length === 0 && !loading && (
          <p style={{ fontSize: "1.2rem" }}>No homes found in that area.</p>
        )}
        {results.map((home) => (
          <div key={home.id} className="card">
            <h3 style={{ color: "#FFD700" }}>{home.owner_name}'s Home</h3>
            <p>
              <strong style={{ color: "#FF4500" }}>Price:</strong> ${home.price}
            </p>
            <p>
              <strong style={{ color: "#FF4500" }}>Location:</strong>{" "}
              {home.address}
            </p>
            <p>
              <strong style={{ color: "#FF4500" }}>Contact:</strong>{" "}
              {home.contact}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
